-- PKG_DMF0048 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
SELECT 'DMF0048_GET_SPREAD_TITLE' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0048_GET_SPREAD_TITLE' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (662031574925, 662031574925) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0048_GET_SPREAD_TITLE' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [C] PKG_DMF0048 BODY 의존 객체 — 행이 나오면 MISSING (컴파일 실패 조건)
SELECT COLUMN_VALUE MISSING FROM TABLE(SYS.ODCIVARCHAR2LIST('DM_PLN_CFM_SELLING_PRICE', 'DM_PLN_SALES_ETC_PLAN', 'DM_PLN_SALES_PLAN', 'DM_PLN_SALES_PLAN_RESULT', 'FN_GET_DM_MKT_OWNER_NAME', 'FN_NEXT_DAY', 'FN_SPLITSTRING', 'FN_STRING_SPLIT', 'GT_GDPS_COLUMN_SETUP', 'GT_GDPS_DM_MST_ITEM_SINGLE_A_V', 'GT_GDPS_DM_MST_ITEM_SINGLE_B_V', 'GT_GDPS_DM_MST_ITEM_SINGLE_ORI_V', 'GT_GDPS_DM_MST_ITEM_SINGLE_V', 'GT_GDPS_RAW_DATA', 'GT_GDPS_SCM_MST_SITE', 'GT_GDPS_SCM_MST_SITE_ITEM', 'GT_GDPS_SELECT_MEASURE', 'GT_GDPS_SHIPMENT_SITE', 'GT_GDPS_SHIPMENT_SITE_ROW', 'GT_GDPS_T', 'PR_SCM_SYS_LOG_BATCH', 'SCM_ADM_LOOKUP_MASTER_DETAIL', 'SCM_ADM_USER_M', 'SCM_MST_CITY', 'SCM_MST_COMPANY_SN', 'SCM_MST_COUNTRY', 'SCM_MST_CUSTOMER', 'SCM_MST_FUTURE_PRICE', 'SCM_MST_ITEM_SN', 'SCM_MST_PROJECT', 'SCM_MST_SHEET_COLUMNS', 'SCM_MST_SHEET_MEASURE', 'SCM_MST_SITE', 'SCM_MST_SITE_CUSTOMER', 'SCM_MST_SITE_ITEM', 'SCM_MST_TITLESET_USER', 'SCM_SYS_CALENDAR_M', 'SCP_ANL_PROBLEM_REPORT_PEGGING', 'SCP_ANL_SHIPMENT_PLAN_FG', 'SCP_PLAN_VERSION_V')) WHERE COLUMN_VALUE NOT IN (SELECT OBJECT_NAME FROM USER_OBJECTS);

-- [D] META 현재값 — API_URL 이 standalone 이면 전환 전, PKG.멤버 면 전환 완료
SELECT API_ID, API_URL FROM SCM_ADM_API_M WHERE API_ID IN ('DMF0048_spreadTitle_SEARCH') ORDER BY API_ID;
SELECT UPPER(PROC_NM) PROC_NM, COUNT(*) CNT FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) IN ('DMF0048_GET_SPREAD_TITLE') OR PROC_NM IN ('PKG_DMF0048.P_DMF0048_GET_SPREAD_TITLE') GROUP BY UPPER(PROC_NM) ORDER BY 1;

-- [E] 앱계정
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0048';
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER = 'SCMP_APP' AND SYNONYM_NAME = 'PKG_DMF0048';
